package com.cpf.starter.file.objectstorage;
import java.net.URI; import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.file.object-storage.s3") public class CpfObjectStorageProperties { private boolean enabled; private String bucket; private String region="us-east-1"; private URI endpoint; private boolean pathStyle=true; private String kmsKeyId; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getBucket(){return bucket;} public void setBucket(String v){bucket=v;} public String getRegion(){return region;} public void setRegion(String v){region=v;} public URI getEndpoint(){return endpoint;} public void setEndpoint(URI v){endpoint=v;} public boolean isPathStyle(){return pathStyle;} public void setPathStyle(boolean v){pathStyle=v;} public String getKmsKeyId(){return kmsKeyId;} public void setKmsKeyId(String v){kmsKeyId=v;} }
